INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Binärfragen (8 Stück, 40%)
('00000000-0000-0000-0000-000000000000', 'Läuft das duale System ohne festen Zeitplan ab?', 2, '[{"text": "Nein", "correct": true, "because": "Zeitplan strukturiert Ablauf"}, {"text": "Ja", "correct": false, "because": "Koordination nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird im dualen System zuerst die Praxis im Betrieb gelernt?', 2, '[{"text": "Nein", "correct": true, "because": "Parallel zu Theorie"}, {"text": "Ja", "correct": false, "because": "Gleichzeitiger Ablauf"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Zwischenprüfungen Teil des Ablaufs im dualen System?', 2, '[{"text": "Ja", "correct": true, "because": "Überprüfen Lernfortschritt"}, {"text": "Nein", "correct": false, "because": "Regelmäßiger Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Ablauf des dualen Systems individuell gestaltet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Flexibilität innerhalb Rahmen"}, {"text": "Nein", "correct": false, "because": "Grundstruktur fest"}]'),
('00000000-0000-0000-0000-000000000000', 'Endet das duale System immer mit einer Abschlussprüfung?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht bei IHK"}, {"text": "Nein", "correct": false, "because": "Standardabschluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Besuch der Berufsschule im Ablauf optional?', 2, '[{"text": "Nein", "correct": true, "because": "Pflichtbestandteil"}, {"text": "Ja", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Azubis im dualen System Projekte im Betrieb umsetzen?', 2, '[{"text": "Ja", "correct": true, "because": "Praxisanwendung wichtig"}, {"text": "Nein", "correct": false, "because": "Teil des Lernprozesses"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Ablauf des dualen Systems ohne IHK-Prüfungen funktionieren?', 2, '[{"text": "Nein", "correct": true, "because": "Prüfungen abschließend"}, {"text": "Ja", "correct": false, "because": "IHK zentral"}]'),

-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Wie ist der typische Ablauf des dualen Systems organisiert?', 2, '[{"text": "Wechsel zwischen Betrieb und Schule", "correct": true, "because": "Grundprinzip Dualität"}, {"text": "Nur Betrieb", "correct": false, "because": "Schule fehlt"}, {"text": "Nur Schule", "correct": false, "because": "Praxis fehlt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert im dualen System nach Vertragsabschluss?', 3, '[{"text": "Start der Ausbildung im Betrieb und Schule", "correct": true, "because": "Beginn des Ablaufs"}, {"text": "Nur Theorieunterricht", "correct": false, "because": "Praxis fehlt"}, {"text": "Sofortige Prüfung", "correct": false, "because": "Zu früh"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase folgt im dualen System auf die Zwischenprüfung?', 2, '[{"text": "Weiterführende Ausbildung", "correct": true, "because": "Fortsetzung bis Abschluss"}, {"text": "Ende der Ausbildung", "correct": false, "because": "Zwischenprüfung mittendrin"}, {"text": "Nur Theorie", "correct": false, "because": "Praxis bleibt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Ziel des Ablaufs im dualen System?', 3, '[{"text": "Berufsabschluss durch IHK-Prüfung", "correct": true, "because": "Endziel Ausbildung"}, {"text": "Nur Praxiserfahrung", "correct": false, "because": "Theorie fehlt"}, {"text": "Vertragserfüllung", "correct": false, "because": "Zu allgemein"}]'),

-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zum Ablauf des dualen Systems?', 4, '[{"text": "Vertragsabschluss", "correct": true, "because": "Startpunkt"}, {"text": "Zwischenprüfung", "correct": true, "because": "Lernkontrolle"}, {"text": "Abschlussprüfung", "correct": true, "because": "Endpunkt"}, {"text": "Urlaub", "correct": false, "because": "Kein Kernbestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert während des dualen Systems regelmäßig?', 3, '[{"text": "Betriebsunterricht", "correct": true, "because": "Praxis"}, {"text": "Berufsschulbesuch", "correct": true, "because": "Theorie"}, {"text": "Leistungsüberprüfung", "correct": true, "because": "Fortschritt"}, {"text": "Firmenwechsel", "correct": false, "because": "Unüblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind im Ablauf des dualen Systems enthalten?', 3, '[{"text": "Einschreibung Berufsschule", "correct": true, "because": "Theoriestart"}, {"text": "Praktische Übungen im Betrieb", "correct": true, "because": "Praxis"}, {"text": "IHK-Prüfungen", "correct": true, "because": "Abschluss"}, {"text": "Studium", "correct": false, "because": "Kein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zum Ablauf eines typischen Ausbildungsjahres?', 4, '[{"text": "Theorieblöcke in der Schule", "correct": true, "because": "Regelmäßig"}, {"text": "Praxis im Betrieb", "correct": true, "because": "Regelmäßig"}, {"text": "Berichtsheft führen", "correct": true, "because": "Pflicht"}, {"text": "Praktikum extern", "correct": false, "because": "Kein Standard"}]'),

-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Ablauf startet mit einem Vertrag. b) Die Abschlussprüfung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vertrag ja, Prüfung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zwischenprüfungen sind Teil des Ablaufs. b) Der Betrieb entscheidet allein über den Ablauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwischenprüfung ja, Ablauf geregelt"}, {"text": "Beides stimmt", "correct": false, "because": "b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Ablauf kombiniert Praxis und Theorie. b) Die Berufsschule ist nur im ersten Jahr dabei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kombination ja, Schule durchgehend"}, {"text": "Beides stimmt", "correct": false, "because": "b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Berichtsheft ist Teil des Ablaufs. b) Der Ablauf endet ohne Prüfung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Berichtsheft ja, Prüfung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) richtig"}]');

